const v2 = [
  f(T.PRO_vocabulary,'TENACIOUS (adjective)','Meaning: Persistent, determined; holding firmly to a purpose.\nSynonyms: persistent, stubborn, determined, steadfast, resolute\nAntonyms: irresolute, wavering, yielding, flexible\nExample: "Her tenacious pursuit of justice finally led to the conviction of the criminal."'),
  f(T.PRO_vocabulary,'COMPLACENT (adjective)','Meaning: Smugly self-satisfied; uncritically satisfied with oneself or one\'s achievements.\nSynonyms: smug, self-satisfied, content, unconcerned, apathetic\nAntonyms: dissatisfied, ambitious, vigilant, concerned\nExample: "The government became complacent about crime after years of relative peace."'),
  f(T.PRO_vocabulary,'IMPARTIAL (adjective)','Meaning: Treating all rivals or disputants equally; fair and just.\nSynonyms: unbiased, neutral, fair, objective, disinterested\nAntonyms: biased, partial, prejudiced, unfair\nExample: "The court must render an impartial decision based on facts, not on personal preferences."'),
  f(T.PRO_vocabulary,'REITERATE (verb)','Meaning: To say or do something again; to repeat.\nSynonyms: repeat, restate, reaffirm, emphasize, iterate\nAntonyms: — (no direct antonym)\nExample: "The examiner reiterated the instructions before the exam began."'),
  f(T.PRO_vocabulary,'ACRIMONIOUS (adjective)','Meaning: Having or showing anger or ill feelings; bitter in manner or temper.\nSynonyms: bitter, hostile, angry, rancorous, caustic\nAntonyms: pleasant, kind, amicable, agreeable\nExample: "The labor dispute led to an acrimonious debate in Congress."'),
  f(T.PRO_vocabulary,'PROLIFIC (adjective)','Meaning: Producing many works, offspring, or results; highly productive.\nSynonyms: productive, fertile, fruitful, creative, inventive\nAntonyms: unproductive, barren, infertile\nExample: "She was a prolific writer, publishing three books in a single year."'),
  f(T.PRO_vocabulary,'ALOOF (adjective)','Meaning: Distant and reserved; not friendly or forthcoming; indifferent.\nSynonyms: distant, detached, reserved, cold, standoffish\nAntonyms: friendly, warm, sociable, approachable\nExample: "The new official appeared aloof and unwilling to engage with the public."'),
  f(T.PRO_vocabulary,'TRANSIENT (adjective)','Meaning: Lasting only for a short time; temporary.\nSynonyms: temporary, brief, momentary, fleeting, short-lived\nAntonyms: permanent, lasting, enduring, long-term\nExample: "His happiness was transient — it faded when he received bad news."'),
  f(T.PRO_vocabulary,'EXACERBATE (verb)','Meaning: To make (a problem, bad situation, or negative feeling) worse.\nSynonyms: worsen, aggravate, intensify, compound, amplify\nAntonyms: improve, alleviate, mitigate, soothe\nExample: "The lack of proper drainage exacerbated the flooding problem."'),
  f(T.PRO_vocabulary,'EQUITABLE (adjective)','Meaning: Fair and impartial; just.\nSynonyms: fair, just, impartial, unbiased, reasonable\nAntonyms: inequitable, unfair, unjust, biased\nExample: "The government must ensure equitable distribution of resources across all regions."'),
  f(T.PRO_vocabulary,'NONCHALANT (adjective)','Meaning: Appearing casually calm and relaxed; not showing anxiety or excitement.\nSynonyms: casual, indifferent, unconcerned, breezy, cool\nAntonyms: anxious, worried, concerned, agitated\nExample: "She was nonchalant about the exam as if it held no difficulty for her."'),
  f(T.PRO_vocabulary,'VERBOSE (adjective) — usage in sentences','Verbose = using too many words; overly wordy.\n\nExample 1: "His verbose report contained 30 pages where 5 would have sufficed."\nExample 2: "The instruction was so verbose that most students gave up reading it."\n\nNote: VERBOSE is often tested alongside its synonym PROLIX and antonym CONCISE/SUCCINCT.\nProlix = excessively long; Terse = brief and abrupt; Succinct = brief and clear.'),
  f(T.PRO_vocabulary,'REPREHENSIBLE (adjective)','Meaning: Deserving censure or condemnation; blameworthy.\nSynonyms: blameworthy, deplorable, disgraceful, shameful, culpable\nAntonyms: praiseworthy, commendable, admirable, laudable\nExample: "His reprehensible behavior in office led to his impeachment."'),
  f(T.PRO_vocabulary,'PRAGMATIC (adjective)','Meaning: Dealing with things sensibly and realistically; practical rather than theoretical.\nSynonyms: practical, realistic, sensible, down-to-earth, matter-of-fact\nAntonyms: idealistic, impractical, unrealistic, theoretical\nExample: "A pragmatic leader focuses on achievable goals rather than grand but unattainable visions."'),
  f(T.PRO_vocabulary,'SUPERFLUOUS (adjective)','Meaning: Unnecessary; more than what is needed or sufficient.\nSynonyms: unnecessary, excess, redundant, surplus, needless\nAntonyms: necessary, essential, vital, indispensable\nExample: "The report contained superfluous information that could be deleted without losing key points."'),
  f(T.PRO_vocabulary,'AMBIVALENT (adjective)','Meaning: Having mixed feelings or contradictory ideas about something or someone.\nSynonyms: undecided, unsure, torn, mixed, conflicted\nAntonyms: certain, decided, sure, definite\nExample: "She felt ambivalent about accepting the promotion — excited about the opportunity but worried about the extra workload."'),
  f(T.PRO_vocabulary,'PERVASIVE (adjective)','Meaning: Spreading widely throughout an area or group; present everywhere.\nSynonyms: widespread, prevalent, ubiquitous, rampant, extensive\nAntonyms: rare, limited, confined, isolated\nExample: "Corruption has become pervasive in some government agencies."'),
  f(T.PRO_vocabulary,'EFFICACIOUS (adjective)','Meaning: Successful in producing a desired or intended result; effective.\nSynonyms: effective, efficient, potent, successful, powerful\nAntonyms: ineffective, inefficacious, futile, useless\nExample: "The new drug proved efficacious in treating the disease in clinical trials."'),
  f(T.PRO_vocabulary,'EMINENT (adjective)','Meaning: Famous and respected within a particular field; outstanding.\nSynonyms: famous, distinguished, renowned, prominent, notable\nAntonyms: obscure, unknown, ordinary, mediocre\nNote: Do NOT confuse with IMMINENT (about to happen) or IMMANENT (inherent).\nExample: "An eminent scientist received the Nobel Prize for her groundbreaking research."'),
  f(T.PRO_vocabulary,'DEPRECATE (verb)','Meaning: To express disapproval of; to belittle.\nSynonyms: belittle, criticize, disapprove of, disparage, denigrate\nAntonyms: praise, commend, approve, appreciate\nExample: "The critic deprecated the government\'s effort as too little too late."'),
  f(T.SUB_vocabulary,'DILIGENT vs. INDUSTRIOUS — difference?','Both mean hardworking, but with nuances:\n\nDILIGENT — emphasis on CARE and THOROUGHNESS in work.\nA diligent student reads every word, takes careful notes.\n\nINDUSTRIOUS — emphasis on the AMOUNT of work and ENERGY put in.\nAn industrious worker completes twice as much as others.\n\nBoth are SYNONYMS in CSE exams. Antonym of both: lazy, idle, slothful.'),
  f(T.SUB_vocabulary,'HONEST (adjective) — synonyms and antonyms','Synonyms of HONEST:\n• truthful, sincere, candid, frank, trustworthy, upright\n\nAntonyms of HONEST:\n• dishonest, deceitful, deceptive, fraudulent, insincere\n\nExample: "An honest civil servant reports irregularities even when it is difficult."'),
  f(T.SUB_vocabulary,'CAPABLE (adjective) — synonyms and antonyms','Synonyms: able, competent, skilled, proficient, qualified\nAntonyms: incapable, incompetent, unskilled, unqualified\n\nExamples:\n• "She is capable of handling complex projects."\n• "An incapable employee may need additional training."'),
  f(T.SUB_vocabulary,'ADEQUATE (adjective) — synonyms and antonyms','Synonyms: sufficient, enough, satisfactory, acceptable\nAntonyms: inadequate, insufficient, deficient, lacking\n\nExample: "The budget was adequate to cover all project costs."\nNote: "Adequate" implies "just enough" — not excellent, but sufficient.'),
  f(T.SUB_vocabulary,'COHERENT (adjective) — synonyms and antonyms','Synonyms: logical, consistent, clear, understandable, organized\nAntonyms: incoherent, confused, illogical, jumbled\n\nExample: "Please write a coherent report that clearly explains the findings."'),
];

