// ── FILIPINO GRAMMAR (Wastong Gamit) ─────────────────────────────────────────
const fg2 = [
  f(T.PRO_grammar_fil,'Wastong gamit ng "bago" at "noong"','"BAGO" = before (referring to a time before another event)\nHalimbawa: "Kinain niya ang almusal BAGO pumasok sa trabaho."\n\n"NOONG" = when / at the time that (past event)\nHalimbawa: "NOONG bata pa siya, mahilig siyang magbasket."\nHalimbawa: "NOONG 1986, nangyari ang People Power Revolution."\n\nTip: BAGO = before (future-leaning reference). NOONG = when (past event reference).'),
  f(T.PRO_grammar_fil,'Wastong gamit ng "sa" at "nasa"','"SA" = to/at/in (direction or general location)\nHalimbawa: "Pupunta ako SA palengke."\n"Nakatira siya SA Maynila."\n\n"NASA" = in/at (specific present location)\nHalimbawa: "NASA palengke si Nanay." (Nanay is at the market right now)\n"NASA kwarto ang libro." (The book is in the room)\n\nTip: NASA = present specific location. SA = general reference.'),
  f(T.PRO_grammar_fil,'Wastong gamit ng "kaya" at "dahil"','"KAYA" = therefore/so/that\'s why (introduces effect/result)\nHalimbawa: "Nahuli siya, KAYA pinalabas sa silid."\n\n"DAHIL" = because (introduces cause/reason)\nHalimbawa: "Pinalabas siya DAHIL nahuli."\n\nRule:\n• DAHIL = reason/cause (why)\n• KAYA = result/effect (so/that\'s why)\nParaan ng pagsubok: "Because" = DAHIL | "That is why/so" = KAYA'),
  f(T.PRO_grammar_fil,'Mga uri ng pangungusap sa Filipino (Sentence Types)','1. PAYAK — simpleng pangungusap (isang paksa, isang pandiwa)\n   "Kumain ang bata."\n\n2. TAMBALAN — dalawang payak na pangungusap na pinagsama\n   "Kumain ang bata at natulog siya."\n\n3. HUGNAYAN — may pangunahing sugnay at pangalawang sugnay\n   "Natulog ang bata sapagkat pagod siya."\n\n4. LANGKAPAN — tambalan at hugnayan na pinagsama\n   "Kumain siya at natulog dahil pagod siya."'),
  f(T.PRO_grammar_fil,'Wastong gamit ng mga pang-angkop (linkers: na, ng, at g-)','Ang PANG-ANGKOP ay nag-uugnay ng mga salita o parirala.\n\n"NA" — ginagamit kung ang nakaraang salita ay NAGTATAPOS sa KATINIG.\nHalimbawa: "mabait NA bata" | "magandang NA araw"\n\n"-NG" (idinudugtong) — ginagamit kung ang nakaraang salita ay NAGTATAPOS sa PATINIG.\nHalimbawa: "magandang araw" | "malaking bahay"\n\nPanuntunan: Katinig + NA = magandang [nagtatapOS sa S]. Patinig + -NG = magand[A]-ng.'),
  f(T.SUB_grammar_fil,'Wastong gamit ng "daw" at "raw"','"DAW" — pagkatapos ng katinig (consonant)\nHalimbawa: "Pumasa DAW sa exam si Pedro."\n\n"RAW" — pagkatapos ng patinig (vowel)\nHalimbawa: "Pumasa RAW si Maria."\n\nParaan: Tingnan ang huling tunog ng nakaraang salita.\n• Katinig (b,k,d,g,h,l,m,n,p,r,s,t,w,y,ng) → DAW\n• Patinig (a,e,i,o,u) → RAW'),
  f(T.SUB_grammar_fil,'Wastong gamit ng "din" at "rin"','"DIN" — pagkatapos ng katinig (consonant)\nHalimbawa: "Pumunta DIN ako sa opisina."\n\n"RIN" — pagkatapos ng patinig (vowel)\nHalimbawa: "Pumunta RIN siya sa opisina."\n\nParaan: Tingnan ang huling letra ng salitang nasa harap.\n• Nagtatapos sa katinig → DIN\n• Nagtatapos sa patinig → RIN'),
];

// ── READING COMPREHENSION STRATEGIES ─────────────────────────────────────────
const readingCards = [
  f(T.PRO_reading_comp,'What is the main idea of a passage and how do you find it?','The MAIN IDEA is the central thought that the entire passage discusses.\n\nStrategies:\n1. Read the FIRST and LAST paragraphs carefully (often contain the main idea)\n2. Look for the TOPIC SENTENCE in each paragraph\n3. Ask: "What is the author primarily talking about?"\n4. The main idea should be supported by ALL details in the passage\n\nNote: Main idea ≠ title (title is just a label). Main idea = central message.'),
  f(T.PRO_reading_comp,'What is an inference in reading comprehension?','An INFERENCE is a conclusion drawn from information NOT directly stated in the text.\n\nProcess:\n1. Use EVIDENCE from the text + your PRIOR KNOWLEDGE\n2. Read between the lines\n3. Ask: "What does this suggest? What can I conclude?"\n\nExample:\nText: "The teacher entered carrying a large stack of papers."\nInference: The teacher may return graded papers or give a test.\n(Not stated directly — you infer from context.)'),
  f(T.PRO_reading_comp,'What is the purpose of a passage? Types of author\'s purpose.','The AUTHOR\'S PURPOSE is the reason why the author wrote the passage.\n\nCommon purposes (PIE):\n• PERSUADE: convince the reader to believe or do something\n  Signal words: should, must, believe, clearly, obviously\n• INFORM/EXPLAIN: give facts, data, information\n  Signal words: is, are, consists of, refers to\n• ENTERTAIN: engage or amuse the reader\n  Signal words: narrative language, story elements\n\nSome add: DESCRIBE, INSTRUCT, COMPARE'),
  f(T.PRO_reading_comp,'What is context clue and what are its types?','CONTEXT CLUES help determine the meaning of an unfamiliar word from surrounding text.\n\nTypes:\n1. DEFINITION: "Hypertension, or high blood pressure, affects millions."\n2. SYNONYM: "The physician, or doctor, prescribed medication."\n3. ANTONYM/CONTRAST: "Unlike the verbose speaker, she was concise."\n4. EXAMPLE: "Citrus fruits, such as oranges and lemons, are rich in Vitamin C."\n5. GENERAL CONTEXT: meaning inferred from the overall passage'),
  f(T.PRO_reading_comp,'What are signal words for text organization patterns?','CAUSE-EFFECT: because, therefore, as a result, consequently, due to, thus\nCOMPARE-CONTRAST: however, on the other hand, similarly, unlike, whereas\nSEQUENCE/CHRONOLOGICAL: first, next, then, finally, subsequently, afterward\nPROBLEM-SOLUTION: the problem is, one solution is, to resolve\nDESCRIPTION: consists of, characterized by, for instance\nOPINION-REASON: I believe, in my view, the reason is, because'),
  f(T.SUB_reading_comp,'How do you answer "what does the word mean in context" questions?','Steps:\n1. Find the word in the passage\n2. Read the SENTENCE and the sentences BEFORE and AFTER it\n3. Look for context clues (synonyms, antonyms, definitions, examples)\n4. Substitute each answer choice — which one makes the most sense?\n5. Choose the answer that best fits the MEANING IN THAT SPECIFIC CONTEXT (not the dictionary definition if it conflicts)\n\nKey: The correct meaning must match the context.'),
  f(T.SUB_reading_comp,'What is the difference between fact and opinion in reading?','FACT: A statement that can be verified or proven.\n• "The Philippines declared independence on June 12, 1898."\n• "Water boils at 100°C at sea level."\n\nOPINION: A personal belief, judgment, or feeling that cannot be objectively proven.\n• "June 12 is the most important day in Philippine history."\n• "The government should increase education spending."\n\nSignal words for opinion: I think, I believe, in my opinion, should, must, best, worst'),
  f(T.PRO_reading_fil,'Mga Hakbang sa Pag-unawa sa Binasang Teksto','1. SURIIN ANG PAMAGAT — nagbibigay ito ng pahiwatig ng paksa.\n2. BASAHIN NANG MABUTI — bigyang-pansin ang bawat talata.\n3. TUKUYIN ANG PANGUNAHING IDEYA — ang sentral na mensahe ng teksto.\n4. HUMANAP NG MGA DETALYE — sumusuporta sa pangunahing ideya.\n5. GUMAWA NG INFERENCE — basahin ang "between the lines."\n6. PANSININ ANG PAHAYAG — ang layunin ng may-akda (nagpapaliwanag, nanghihikayat, nagkukuwento).\n7. SURIIN ANG BOKABULARYO — gamitin ang context clues para sa hindi pamilyar na salita.'),
  f(T.SUB_reading_fil,'Paano tumukoy ng pangunahing ideya ng isang talata?','1. Hanapin ang PAKSA (topic) — ang pinagsasalitaan.\n2. Hanapin ang PAKSA-PANGUNGUSAP (topic sentence) — madalas nasa unang pangungusap.\n3. Itanong: "Anong mensahe ang gustong iparating ng may-akda?"\n4. Ang tamang sagot ay dapat suportahan ng LAHAT ng pangungusap sa talata.\n\nMaling sagot: masyadong malawak (hindi eksakto) o masyadong makitid (isang detalye lamang).'),
];

// ── PARAGRAPH ORGANIZATION (Filipino) ────────────────────────────────────────
