// Combine batch 2
const BATCH2 = [
  ...g2, ...v2, ...fv2, ...fg2, ...readingCards, ...pf2,
  ...dataCards, ...logicCards, ...numCards2, ...con2, ...lawsCards, ...cler2,
];

console.log(`\n📚 Batch 2: ${BATCH2.length} more flashcards to insert\n`);

const BATCH_SIZE = 50;
let inserted = 0, failed = 0;

for (let i = 0; i < BATCH2.length; i += BATCH_SIZE) {
  const batch = BATCH2.slice(i, i + BATCH_SIZE);
  const { error } = await sb.from('flashcards').insert(batch);
  if (error) {
    console.error(`  ✗ Batch ${Math.floor(i/BATCH_SIZE)+1}: ${error.message}`);
    failed += batch.length;
  } else {
    inserted += batch.length;
    process.stdout.write(`  ✓ Inserted ${inserted}/${BATCH2.length}\r`);
  }
}

const { count: total } = await sb.from('flashcards').select('*', { count: 'exact', head: true });
console.log(`\n\n✅ Batch 2 done! ${inserted} inserted, ${failed} failed.`);
console.log(`📊 TOTAL flashcards in database: ${total}`);
